import hashlib,os,re,subprocess,sys
fail=[]
def raw(p): return open(p,'rb').read()
def txt(p): return raw(p).decode('utf-8')
for i in d['inputs']:
    if hashlib.sha256(raw(i['path'])).hexdigest()!=i['rawSha256']: fail.append('input drift '+i['path'])
D=d['designTargets']['path']
if hashlib.sha256(raw(D)).hexdigest()!=d['designTargets']['finalSha256']: fail.append('design hash drift')
for p,cap in d['lineCaps'].items():
    if os.path.exists(p):
        n=len(txt(p).splitlines())
        if n>cap: fail.append('line cap %s %d>%d'%(p,n,cap))
    elif p!=d['exactPaths'][2]: fail.append('missing '+p)
t=txt(D)
rx=re.compile(r'(?m)^### (S\d\d) \| (\d+)-(\d+) \| (\d+) s$')
found=[(m.group(1),int(m.group(2)),int(m.group(3)),int(m.group(4))) for m in rx.finditer(t)]
want=[(s['id'],s['start'],s['end'],s['duration']) for s in d['scenes']]
if found!=want: fail.append('scene headers differ from evidence %r'%(found,))
cur=0
for sid,a,b,du in found:
    if a!=cur: fail.append('gap/overlap at '+sid)
    if b-a!=du: fail.append('duration mismatch '+sid)
    cur=b
if cur!=d['targetSeconds']: fail.append('total %d != %d'%(cur,d['targetSeconds']))
if len({x[0] for x in found})!=len(found): fail.append('duplicate scene id')
blocks=re.split(r'(?m)^(?=### S\d\d \|)',t)[1:]
if len(blocks)!=len(d['scenes']): fail.append('scene block count')
for blk,s in zip(blocks,d['scenes']):
    for label in ('Narration','On-screen','Visual intent','Asset needs','Claims'):
        if not re.search(r'(?m)^- %s: .+$'%label,blk): fail.append('%s missing %s'%(s['id'],label))
    nar=re.search(r'(?m)^- Narration: (.+)$',blk).group(1)
    words=len(nar.split()); dens=words/s['duration']
    if dens>d['maxNarrationWordsPerSecond']: fail.append('density %s %.2f'%(s['id'],dens))
    for bad in d['narrationMustNotContain']:
        if re.search(r'\b'+re.escape(bad)+r'\b',nar): fail.append('narration token %s in %s'%(bad,s['id']))
    cl=[c.strip() for c in re.search(r'(?m)^- Claims: (.+)$',blk).group(1).split(',')]
    if cl!=s['claims']: fail.append('claims differ '+s['id'])
    for c in cl:
        e=d['claims'].get(c)
        if not e or not all(e.get(k) for k in ('claim','source','locator','proofClass','limitation')): fail.append('claim incomplete '+c)
        elif e['source'] not in {i['path'] for i in d['inputs']}: fail.append('claim source not hashed '+c)
    if s['id'] in d['illustrationScenes'] and 'VÍ DỤ MINH HỌA' not in blk: fail.append('illustration card missing '+s['id'])
used={c for s in d['scenes'] for c in s['claims']}
if used!=set(d['claims']): fail.append('unused or undefined claims %r'%(sorted(used^set(d['claims'])),))
for tok in d['mustContain']:
    if tok not in t: fail.append('missing '+tok)
for tok in d['mustNotContain']:
    if tok in t: fail.append('forbidden '+tok)
sec=t.split('## Production-Readiness Checklist')[1].split('## Proof Anchors')[0]
rows=[l for l in sec.splitlines() if l.startswith('| ') and not l.startswith('| Mục')]
if len(rows)<8: fail.append('checklist rows %d'%len(rows))
for r in rows:
    if r.split('|')[2].strip() not in d['checklistRequiredStatuses']: fail.append('checklist status '+r)
for m in re.finditer(r'\]\(([^)#]+)(#[^)]*)?\)',t):
    tgt=m.group(1)
    if '://' in tgt: fail.append('external link '+tgt); continue
    if not os.path.exists(os.path.normpath(os.path.join(os.path.dirname(D),tgt))): fail.append('broken link '+tgt)
st=subprocess.run(['git','status','--short','--untracked-files=all'],capture_output=True,text=True).stdout.splitlines()
paths=sorted(l[3:] for l in st)
if paths!=sorted(d['exactPaths']): fail.append('manifest differs %r'%(paths,))
if any(not l.startswith('??') for l in st): fail.append('tracked path modified')
head=subprocess.run(['git','rev-parse','HEAD'],capture_output=True,text=True).stdout.strip()
if head!=d['executionBaseHead']: fail.append('HEAD moved '+head)
print('PASS_STATIC_ONLY' if not fail else 'FAIL')
for f in fail: print(' -',ascii(f))
sys.exit(1 if fail else 0)
